// Runs once per resume. Turns Claude's reply into one clean row for Google Sheets.
const res = $input.item.json;
const email = $('Gmail Trigger').item.json;

// Claude returns a list of content blocks; we only want the text ones.
const text = (res.content || [])
  .filter(block => block.type === 'text')
  .map(block => block.text)
  .join('');

const data = JSON.parse(text);

return {
  json: {
    'Received At': email.date || new Date().toISOString(),
    'Name': data.name,
    'Email': (data.email || '').toLowerCase(),
    'Phone': data.phone,
    'Score': data.score,
    'Recommendation': data.recommendation,
    'Summary': data.summary,
    'Top Skills': (data.top_skills || []).join(', '),
    'Missing Skills': (data.missing_skills || []).join(', '),
  }
};
